#!/usr/bin/env python3
"""forge_install13.py - the daily frame, OPTIMIZE/IMMERSE tags, mushin, recurrence.

Run from ~/Desktop/forge-daily-brief on the gh-pages branch.
Touches forge-evening-debrief.html ONLY. Hand-maintained: NO workflow run needed.
"""
import base64, gzip, hashlib, os, shutil, sys, datetime

TARGET   = "forge-evening-debrief.html"
PRE_SHA  = "ac138a03a640ce2366a173485e7c2d71337bf2765e51f8e0b3efa9ecf3191a4a"
POST_SHA = "5b89621a64ca1f2bd0a7be918acb281671d0c08a81bbe235a18bdf7e1a5e3183"
CHECKS = [("install13", 11), ("forge-frame", 1), ("forge-mushin", 1),
          ("recurringUnfinished", 2), ("enoughVerdict", 2), ("renderMushinRow", 2),
          ("initFrame", 2), ("saveFrame", 2), ("renderFrameSummary", 2),
          ("syncPush(K_TOP5)", 2), ("syncPush(K_BACKLOG)", 1), ("install11", 1)]
BLOB = ""

def die(m):
    print("FAILED: " + m)
    print("Nothing was written. Your files are untouched.")
    sys.exit(1)

if not os.path.exists(TARGET):
    die("cannot find " + TARGET + " - are you in ~/Desktop/forge-daily-brief on gh-pages?")

cur = open(TARGET, "rb").read()
cur_sha = hashlib.sha256(cur).hexdigest()
if cur_sha == POST_SHA:
    print("Already installed. Nothing to do.")
    sys.exit(0)
if cur_sha != PRE_SHA:
    die("%s changed since this patch was built.\n  expected %s\n  found    %s"
        % (TARGET, PRE_SHA[:16], cur_sha[:16]))

try:
    payload = gzip.decompress(base64.b64decode(BLOB)).decode("utf-8")
except Exception as e:
    die("payload did not decode - the paste was probably truncated (%s)" % e)

if hashlib.sha256(payload.encode("utf-8")).hexdigest() != POST_SHA:
    die("payload checksum mismatch - truncated or corrupted paste")

for needle, want in CHECKS:
    got = payload.count(needle)
    if got != want:
        die("payload self-check failed: %s appears %d times, expected %d" % (needle, got, want))

stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
backup = TARGET + ".install13.bak-" + stamp
shutil.copy2(TARGET, backup)
open(TARGET, "w", encoding="utf-8").write(payload)

if hashlib.sha256(open(TARGET, "rb").read()).hexdigest() != POST_SHA:
    shutil.copy2(backup, TARGET)
    die("written file did not verify - restored from backup")

print("OK  " + TARGET + " patched.")
print("    backup: " + backup)
print("")
print("Next, one command per line:")
print("  git add forge-evening-debrief.html")
print("  git commit -m \"install13: daily frame, optimize/immerse, mushin\"")
print("  git pull --rebase")
print("  git push")
print("")
print("No workflow run needed. This file is hand-maintained.")
